import json
import os
import sys
from typing import Any, Dict, List

TRIAL_ID_PATH = "/logs/trial_id"
USER_ID = "zealt-user01"
WEBHOOK_URL = os.environ.get("COMPOSIO_WEBHOOK_URL", "http://localhost:8000/webhook")
TRIGGERS_LOG_PATH = "/home/user/triggers.log"


def read_trial_id() -> str:
    try:
        with open(TRIAL_ID_PATH, "r", encoding="utf-8") as handle:
            return handle.read().strip()
    except FileNotFoundError as exc:
        raise RuntimeError(f"trial_id file not found at {TRIAL_ID_PATH}") from exc


def ensure_repo(repo_name: str) -> None:
    """Create GitHub repo if it does not exist.

    Uses GITHUB_TOKEN environment variable. If creation fails because
    it already exists, we continue.
    """
    token = os.environ.get("GITHUB_TOKEN")
    if not token:
        print("GITHUB_TOKEN not set; skipping repo creation.")
        return

    import requests  # pylint: disable=import-outside-toplevel

    api_url = "https://api.github.com/user/repos"
    headers = {
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github+json",
    }
    payload = {"name": repo_name, "private": True}

    response = requests.post(api_url, headers=headers, json=payload, timeout=30)
    if response.status_code in (201, 202):
        print(f"Created repository {repo_name}.")
        return
    if response.status_code == 422 and "already exists" in response.text:
        print(f"Repository {repo_name} already exists.")
        return

    response.raise_for_status()


def init_composio_session() -> Any:
    """Initialize Composio session with fallback imports."""
    try:
        from composio import Composio  # type: ignore

        api_key = os.environ.get("COMPOSIO_API_KEY")
        if not api_key:
            raise RuntimeError("COMPOSIO_API_KEY environment variable is required.")
        return Composio(api_key=api_key)
    except ImportError:
        try:
            from composio import ComposioToolSet  # type: ignore

            api_key = os.environ.get("COMPOSIO_API_KEY")
            if not api_key:
                raise RuntimeError("COMPOSIO_API_KEY environment variable is required.")
            return ComposioToolSet(api_key=api_key)
        except ImportError as exc:
            raise RuntimeError("Composio SDK not installed. Install composio.") from exc


